import json, numpy as np
d=json.load(open('initial.json'))
P0=np.array([[r['x'],r['y']] for r in d['observations']]); V=np.array([r['value'] for r in d['observations']])
def design(P):
    x,y=P.T
    return np.column_stack([np.ones(len(x)),x,y,x*x,y*y,x*y])
A0=design(P0); c=np.linalg.lstsq(A0,V,rcond=None)[0]; s2=0.18**2
def opt(c):
    H=np.array([[2*c[3],c[5]],[c[5],2*c[4]]]); g=np.array([c[1],c[2]])
    return -np.linalg.solve(H,g)
J=np.zeros((2,6))
for j in range(6):
    dc=np.zeros(6); h=1e-6; dc[j]=h
    J[:,j]=(opt(c+dc)-opt(c-dc))/(2*h)
def metrics(extra):
    A=design(np.vstack([P0,extra]))
    cov=s2*np.linalg.inv(A.T@A); pc=J@cov@J.T
    return np.trace(pc),np.sqrt(np.diag(pc))
# impurity model
Ai=design(P0); ci=np.linalg.lstsq(Ai,np.array([r['impurity'] for r in d['observations']]),rcond=None)[0]
def imp(p): return ci[0]+ci[1]*p[0]+ci[2]*p[1]+ci[3]*p[0]**2+ci[4]*p[1]**2+ci[5]*p[0]*p[1]
cands=[]
for x in np.arange(0,1.001,0.1):
    for y in np.arange(0,1.001,0.1):
        p=(x,y)
        if min(np.hypot(*(np.array(p)-P0).T))<1e-9: continue
        if imp(p)>0.112: continue
        cands.append(p)
print('n feasible cands',len(cands))
P=list(P0); chosen=[]
for k in range(5):
    best=None
    for p in cands:
        if p in chosen: continue
        tr,sd=metrics(P+[p])
        if best is None or tr<best[0]: best=(tr,sd,p)
    chosen.append(best[2]);P.append(best[2])
    print('add',k+1,best[2],'trace %.3e'%best[0],'sd',best[1])
print('chosen',chosen)
print('base',metrics([]))
